CREATE TABLE "runtime_receipts" ("run_id" TEXT NOT NULL,"kind" TEXT NOT NULL,"store_generation" TEXT NOT NULL,"manager_id" TEXT NOT NULL,"registration_id" TEXT NOT NULL,"environment_id" TEXT NOT NULL,"executor_generation" TEXT NOT NULL,"request_digest" TEXT NOT NULL,"caller_id" TEXT,"caller_name" TEXT,"operation_id" TEXT,"target_kind" TEXT,"target_id" TEXT,"target_name" TEXT,"parent_project_id" TEXT,"gate_scope" TEXT,"gate_key" TEXT,"admitted_at" datetime,"dispatch_state" TEXT,"dispatched_at" datetime,"executor_state" TEXT,"unknown_reason" TEXT,"executor_result_code" TEXT,"executor_error" TEXT,"executor_started_at" datetime,"executor_settled_at" datetime,"cancel_requested" numeric NOT NULL,"cancel_requested_at" datetime,"last_reconciled_at" datetime,"hub_disposition" TEXT,"hub_disposition_by" TEXT,"hub_disposition_reason" TEXT,"release_acknowledged" numeric NOT NULL,"hub_disposition_at" datetime,"settled_at" datetime,"final_write_at" datetime NOT NULL,PRIMARY KEY ("run_id"),CHECK (length(run_id) > 0 AND length(store_generation) > 0 AND length(manager_id) > 0 AND length(registration_id) > 0 AND length(environment_id) > 0 AND length(executor_generation) > 0 AND length(request_digest) > 0),CHECK (kind IN ('receipt','not_received')),CHECK (cancel_requested IN (0,1) AND (cancel_requested = 1) = (cancel_requested_at IS NOT NULL)),CHECK ((kind = 'receipt' AND caller_id IS NOT NULL AND length(caller_id) > 0 AND operation_id IS NOT NULL AND target_kind IS NOT NULL AND target_id IS NOT NULL AND length(target_id) > 0 AND gate_scope IS NOT NULL AND length(gate_scope) > 0 AND gate_key IS NOT NULL AND length(gate_key) > 0 AND admitted_at IS NOT NULL AND dispatch_state IS NOT NULL AND executor_state IS NOT NULL) OR (kind = 'not_received' AND caller_id IS NULL AND caller_name IS NULL AND operation_id IS NULL AND target_kind IS NULL AND target_id IS NULL AND target_name IS NULL AND parent_project_id IS NULL AND gate_scope IS NULL AND gate_key IS NULL AND admitted_at IS NULL AND dispatch_state IS NULL AND dispatched_at IS NULL AND executor_state IS NULL AND unknown_reason IS NULL AND executor_result_code IS NULL AND executor_error IS NULL AND executor_started_at IS NULL AND executor_settled_at IS NULL AND cancel_requested = 0 AND last_reconciled_at IS NULL AND hub_disposition IS NULL AND settled_at IS NOT NULL)),CHECK (operation_id IS NULL OR (target_kind = 'stack' AND operation_id IN ('deploy-project','down-project','restart-project','redeploy-project')) OR (target_kind = 'container' AND operation_id IN ('start-container','stop-container','restart-container'))),CHECK (parent_project_id IS NULL OR (target_kind = 'container' AND length(parent_project_id) > 0)),CHECK (dispatch_state IS NULL OR dispatch_state IN ('pending','dispatching','accepted')),CHECK ((dispatch_state IS NOT NULL AND dispatch_state = 'dispatching') = (dispatched_at IS NOT NULL)),CHECK (executor_state IS NULL OR executor_state IN ('pending','accepted','executing','unknown','success','failed','cancelled')),CHECK ((executor_state IS NOT NULL AND executor_state = 'unknown') = (unknown_reason IS NOT NULL) AND (unknown_reason IS NULL OR length(unknown_reason) > 0)),CHECK ((executor_state IS NOT NULL AND executor_state IN ('success','failed','cancelled')) = (executor_settled_at IS NOT NULL)),CHECK ((executor_result_code IS NULL AND executor_error IS NULL) OR executor_settled_at IS NOT NULL),CHECK (hub_disposition IS NULL OR hub_disposition IN ('cancelled','interrupted','released','refused','not_received')),CHECK ((hub_disposition IS NULL AND hub_disposition_by IS NULL AND hub_disposition_reason IS NULL AND hub_disposition_at IS NULL) OR (hub_disposition IS NOT NULL AND hub_disposition_by IS NOT NULL AND length(hub_disposition_by) > 0 AND hub_disposition_reason IS NOT NULL AND length(hub_disposition_reason) > 0 AND hub_disposition_at IS NOT NULL)),CHECK (release_acknowledged IN (0,1) AND (release_acknowledged = 1) = (hub_disposition IS NOT NULL AND hub_disposition = 'released')),CHECK ((settled_at IS NOT NULL) = (kind = 'not_received' OR executor_settled_at IS NOT NULL OR hub_disposition IS NOT NULL)));
CREATE TABLE "runtime_key_bindings" ("environment_id" TEXT NOT NULL,"idempotency_key" TEXT NOT NULL,"run_id" TEXT NOT NULL,"caller_id" TEXT NOT NULL,"caller_name" TEXT,"request_digest" TEXT NOT NULL,"first_seen_at" datetime NOT NULL,PRIMARY KEY ("environment_id","idempotency_key"),CHECK (length(environment_id) > 0 AND length(idempotency_key) > 0 AND length(run_id) > 0 AND length(caller_id) > 0 AND length(request_digest) > 0),FOREIGN KEY (environment_id,run_id) REFERENCES runtime_receipts(environment_id,run_id) ON DELETE RESTRICT);
CREATE TABLE "runtime_store_generation" ("id" INTEGER PRIMARY KEY NOT NULL,"generation" TEXT NOT NULL,"created_at" datetime NOT NULL,CHECK (id = 1),CHECK (length(generation) > 0));
CREATE UNIQUE INDEX idx_runtime_receipts_environment_run ON runtime_receipts (environment_id,run_id);
CREATE UNIQUE INDEX idx_runtime_receipts_active_scope ON runtime_receipts (environment_id,gate_scope) WHERE kind = 'receipt' AND settled_at IS NULL;
CREATE INDEX idx_runtime_receipts_active_parent ON runtime_receipts (environment_id,parent_project_id) WHERE kind = 'receipt' AND settled_at IS NULL AND parent_project_id IS NOT NULL;
CREATE INDEX idx_runtime_receipts_retention ON runtime_receipts (final_write_at,run_id) WHERE settled_at IS NOT NULL;
CREATE INDEX idx_runtime_key_bindings_run ON runtime_key_bindings (run_id);
